INSERT INTO restaurant_config (key, value) VALUES ('menu', '[{"id":"dish-1","name":"Burrata & Heirloom","category":"Starters","price":295,"available":true,"description":"Creamy burrata, tomatoes and basil oil."},{"id":"dish-2","name":"Crispy Truffle Fries","category":"Starters","price":185,"available":true,"description":"Golden fries, parmesan and truffle."},{"id":"dish-3","name":"Ember-Grilled Chicken","category":"Mains","price":425,"available":true,"description":"Herb-marinated chicken with buttery mash."},{"id":"dish-4","name":"Wild Mushroom Pasta","category":"Mains","price":365,"available":true,"description":"Creamy mushrooms, parmesan and fresh herbs."},{"id":"dish-5","name":"Smoky Paneer Bowl","category":"Mains","price":325,"available":true,"description":"Tandoori paneer, grains and mint yoghurt."},{"id":"dish-6","name":"Warm Chocolate Cake","category":"Desserts","price":195,"available":true,"description":"Rich chocolate with vanilla cream."},{"id":"dish-7","name":"Classic Tiramisu","category":"Desserts","price":210,"available":true,"description":"Espresso-soaked layers and cocoa."},{"id":"dish-8","name":"Iced Matcha Latte","category":"Drinks","price":165,"available":true,"description":"Matcha, cold milk and ice."}]'::jsonb) ON CONFLICT (key) DO NOTHING;
